    Lemma uP_bad : q < e -> c <> 34 -> c < 128 -> c <> 92 ->
      evt rsegs (fun ms => exists (a4' : word) m',
          ms = MS (mkR (Z_to_bv 64 0x5f0e0) (Z_to_bv 64 (bv_unsigned sp + -112)) gp tp t0 t1 t2 (Z_to_bv 64 q) (Z_to_bv 64 (bv_unsigned a0 + 88)) a0 (Z_to_bv 64 q) (Z_to_bv 64 1) (Z_to_bv 64 0xf5760) a4' a5 a6 a7 (Z_to_bv 64 e) (Z_to_bv 64 st) u a0 (Z_to_bv 64 (bv_unsigned a0 + 1)) (Z_to_bv 64 34) (Z_to_bv 64 2147483646) (Z_to_bv 64 92) s10 s11 t3 t4 t5 t6)
                  F (wz RP_FAIL) fc None m' (seg_rom rsegs)
          /\ munch [(bv_unsigned sp + -112, bv_unsigned sp + -104)]%Z m m' /\ wmono rsegs m m' /\ mem_inv rsegs m'
          /\ rw_cells rsegs m' (bv_unsigned sp + -112) [C8 (Z_to_bv 64 (tot + (q - st)))])
